property.value:
// Tints the tag with the pill colours shown in Change Review: Color in the light theme and
// Color (Dark Mode) in the dark theme, each falling back to the other, and with neither set, to the
// colour Change Review derives from the name.
const settings = getStereotype("File Classification Settings");
const read = (name) => (settings?.getProperty(name)?.getValue() ?? "").trim();
// Only plain CSS colour syntax (#hex, names, rgb()/hsl()) so a value can't break out of the style rule.
const valid = (value) => value !== "" && /^[#a-zA-Z0-9(),.%\s-]+$/.test(value);

// Mirrors DeriveColourFromName in the client's FileClassificationService: FNV-1a over the UTF-8 bytes of
// the trimmed, lower-cased name picks the hue. Change both together.
const deriveColourFromName = (name) => {
    const encoded = encodeURIComponent(name.trim().toLowerCase());
    let hash = 2166136261;
    for (let i = 0; i < encoded.length; i++) {
        let byte = encoded.charCodeAt(i);
        if (encoded[i] === "%") {
            byte = parseInt(encoded.substr(i + 1, 2), 16);
            i += 2;
        }
        hash = Math.imul(hash ^ byte, 16777619) >>> 0;
    }
    return "hsl(" + (hash % 360) + ", 58%, 45%)";
};

const colour = valid(read("Color")) ? read("Color") : null;
const darkModeColour = valid(read("Color (Dark Mode)")) ? read("Color (Dark Mode)") : null;
const light = colour ?? darkModeColour ?? deriveColourFromName(getName() ?? "");
const dark = darkModeColour ?? light;

// The SVG is rendered inline, so its <style> and gradient id are page-wide: both must be unique to this
// element. Like the default icon, the tag is a vertical gradient: a lighter tint of the colour at the top
// down to a slightly deeper shade at the bottom.
const key = "fileClassificationIcon_" + getId().replace(/[^a-zA-Z0-9]/g, "");
const stops = (prefix, c) => prefix + '.' + key + '_top { stop-color: color-mix(in srgb, ' + c + ' 65%, white); } '
    + prefix + '.' + key + '_bottom { stop-color: color-mix(in srgb, ' + c + ' 85%, black); } ';
const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 50 50">'
    + '<style>' + stops('', light) + stops('[data-theme="dark"] ', dark) + '</style>'
    + '<defs><linearGradient id="' + key + '" x1="0" y1="0" x2="0" y2="1">'
    + '<stop offset="0" class="' + key + '_top"/><stop offset="1" class="' + key + '_bottom"/>'
    + '</linearGradient></defs>'
    + '<path fill="url(#' + key + ')" fill-rule="evenodd" '
    + 'd="M5 8h28l17 17-17 17H5a5 5 0 0 1-5-5V13a5 5 0 0 1 5-5Z M11 20a5 5 0 1 0 0 10 5 5 0 0 0 0-10Z"/></svg>';

// The icon renderer base64-decodes every SVG data URI, and btoa isn't available to designer scripts.
// The SVG is ASCII-only, so encode its char codes directly.
const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
let base64 = "";
for (let i = 0; i < svg.length; i += 3) {
    const n = (svg.charCodeAt(i) << 16) | ((svg.charCodeAt(i + 1) | 0) << 8) | (svg.charCodeAt(i + 2) | 0);
    base64 += alphabet[(n >> 18) & 63] + alphabet[(n >> 12) & 63]
        + (i + 1 < svg.length ? alphabet[(n >> 6) & 63] : "=")
        + (i + 2 < svg.length ? alphabet[n & 63] : "=");
}
return "data:image/svg+xml;base64," + base64;
